-- ===================== 20260101000002_triggers.sql =====================
-- Branch Review OS - migration 2: triggers.
-- All trigger functions are SECURITY DEFINER so they can maintain derived state
-- (e.g. a lead's current rating) regardless of who triggered them. They never
-- expose data: they only write rows the caller already had the right to create.

-- ================================================================ updated_at everywhere
do $$
declare t text;
begin
  foreach t in array array[
    'branches','profiles','projects','cold_reasons','next_action_types','review_cycle',
    'channel_partners','leads','interactions','cp_interactions','bookings',
    'booking_status_history','targets','review_sessions','review_actions']
  loop
    execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()',
                   t || '_set_updated_at', t);
  end loop;
end $$;

-- ================================================================ profiles guard
-- Signed-in users (auth.uid() not null) can only change their own harmless fields.
-- Role / branch / reporting line / active flag are changed server-side with the service key.
create or replace function public.profiles_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null then
    if new.role        is distinct from old.role
    or new.branch_id   is distinct from old.branch_id
    or new.reports_to  is distinct from old.reports_to
    or new.active      is distinct from old.active
    or new.designation is distinct from old.designation
    or new.email       is distinct from old.email
    or new.deleted_at  is distinct from old.deleted_at then
      raise exception 'You cannot change role, branch, reporting line, status or designation from the app. Ask an admin.'
        using errcode = '42501';
    end if;
    if new.must_change_password and not old.must_change_password then
      raise exception 'must_change_password can only be switched on by an admin' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;
create trigger profiles_guard before update on public.profiles
  for each row execute function public.profiles_guard();

-- ================================================================ channel partner dedupe key
create or replace function public.cp_set_key() returns trigger
language plpgsql as $$
declare digits text;
begin
  if new.branch_id is null then
    select branch_id into new.branch_id from public.profiles where id = auth.uid();
  end if;
  digits := right(regexp_replace(coalesce(new.phone, ''), '\D', '', 'g'), 10);
  if length(digits) = 10 then
    new.normalized_key := 'p:' || digits;
  else
    new.normalized_key := 'n:' || lower(regexp_replace(coalesce(new.name, ''), '[^[:alnum:]]', '', 'g'))
                          || '|' || lower(regexp_replace(coalesce(new.firm, ''), '[^[:alnum:]]', '', 'g'));
  end if;
  return new;
end $$;
create trigger channel_partners_key before insert or update of name, firm, phone, branch_id on public.channel_partners
  for each row execute function public.cp_set_key();

-- ================================================================ leads: branch from owner
create or replace function public.leads_before_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.branch_id is null then
    select branch_id into new.branch_id from public.profiles where id = new.owner_id;
  end if;
  return new;
end $$;
create trigger leads_before_insert before insert on public.leads
  for each row execute function public.leads_before_insert();

-- ================================================================ lead state from interactions
-- The lead row is a cache of its newest (by occurred_on, then insertion time) live interaction.
-- Back-dated entries therefore never overwrite newer state, and soft-deleting an
-- interaction rolls the lead back to the previous one.
create or replace function public.refresh_lead_from_interactions(p_lead uuid) returns void
language plpgsql security definer set search_path = public as $$
declare x public.interactions%rowtype;
begin
  select * into x from public.interactions
   where lead_id = p_lead and deleted_at is null
   order by occurred_on desc, created_at desc
   limit 1;
  if not found then return; end if;

  update public.leads l set
    current_rating   = x.rating_after,
    last_touch_at    = (x.occurred_on::timestamp at time zone 'Asia/Kolkata'),
    next_action      = x.next_action,
    next_action_date = x.next_action_date,
    cold_reason      = case when x.rating_after = 'cold' then x.cold_reason else null end,
    plot_names       = case when cardinality(x.plot_names) > 0 then x.plot_names else l.plot_names end
  where l.id = p_lead;
end $$;

create or replace function public.interactions_before_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare l public.leads%rowtype;
begin
  select * into l from public.leads where id = new.lead_id and deleted_at is null;
  if not found then
    raise exception 'Lead % does not exist', new.lead_id using errcode = '23503';
  end if;
  new.branch_id    := l.branch_id;
  new.associate_id := coalesce(new.associate_id, auth.uid(), l.owner_id);

  -- rating_before = rating_after of the chronologically previous interaction (NULL = first contact)
  if new.rating_before is null then
    select i.rating_after into new.rating_before
      from public.interactions i
     where i.lead_id = new.lead_id and i.deleted_at is null
       and (i.occurred_on, i.created_at) < (new.occurred_on, new.created_at)
     order by i.occurred_on desc, i.created_at desc
     limit 1;
  end if;
  return new;
end $$;
create trigger interactions_before_insert before insert on public.interactions
  for each row execute function public.interactions_before_insert();

create or replace function public.interactions_after_change() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform public.refresh_lead_from_interactions(new.lead_id);
  return null;
end $$;
create trigger interactions_after_insert after insert on public.interactions
  for each row execute function public.interactions_after_change();
create trigger interactions_after_softdelete after update of deleted_at on public.interactions
  for each row when (old.deleted_at is distinct from new.deleted_at)
  execute function public.interactions_after_change();

-- ================================================================ CP state from cp_interactions
create or replace function public.refresh_cp_from_interactions(p_cp uuid) returns void
language plpgsql security definer set search_path = public as $$
declare x public.cp_interactions%rowtype;
begin
  select * into x from public.cp_interactions
   where cp_id = p_cp and deleted_at is null
   order by occurred_on desc, created_at desc
   limit 1;
  if not found then return; end if;

  update public.channel_partners c set
    current_rating   = x.rating_after,
    last_touch_at    = (x.occurred_on::timestamp at time zone 'Asia/Kolkata'),
    next_action      = x.next_action,
    next_action_date = x.next_action_date
  where c.id = p_cp;
end $$;

create or replace function public.cp_interactions_before_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare c public.channel_partners%rowtype;
begin
  select * into c from public.channel_partners where id = new.cp_id and deleted_at is null;
  if not found then
    raise exception 'Channel partner % does not exist', new.cp_id using errcode = '23503';
  end if;
  new.branch_id    := c.branch_id;
  new.associate_id := coalesce(new.associate_id, auth.uid());

  if new.rating_before is null then
    select i.rating_after into new.rating_before
      from public.cp_interactions i
     where i.cp_id = new.cp_id and i.deleted_at is null
       and (i.occurred_on, i.created_at) < (new.occurred_on, new.created_at)
     order by i.occurred_on desc, i.created_at desc
     limit 1;
  end if;
  return new;
end $$;
create trigger cp_interactions_before_insert before insert on public.cp_interactions
  for each row execute function public.cp_interactions_before_insert();

create or replace function public.cp_interactions_after_change() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform public.refresh_cp_from_interactions(new.cp_id);
  return null;
end $$;
create trigger cp_interactions_after_insert after insert on public.cp_interactions
  for each row execute function public.cp_interactions_after_change();
create trigger cp_interactions_after_softdelete after update of deleted_at on public.cp_interactions
  for each row when (old.deleted_at is distinct from new.deleted_at)
  execute function public.cp_interactions_after_change();

-- ================================================================ bookings
create or replace function public.bookings_before_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare l public.leads%rowtype;
begin
  select * into l from public.leads where id = new.lead_id and deleted_at is null;
  if not found then
    raise exception 'Lead % does not exist', new.lead_id using errcode = '23503';
  end if;
  new.branch_id    := l.branch_id;
  new.associate_id := coalesce(new.associate_id, auth.uid(), l.owner_id);
  new.project_id   := coalesce(new.project_id, l.project_id);
  new.source       := coalesce(new.source, l.source);
  new.cp_id        := coalesce(new.cp_id, l.cp_id);
  return new;
end $$;
create trigger bookings_before_insert before insert on public.bookings
  for each row execute function public.bookings_before_insert();

-- a lead is 'booked' while it has at least one live booking_done / agreement_signed booking
-- (a lead marked 'lost' stays lost until someone reopens it).
create or replace function public.refresh_lead_status(p_lead uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  update public.leads l set status = case
      when exists (select 1 from public.bookings b
                    where b.lead_id = p_lead and b.deleted_at is null
                      and b.status in ('booking_done', 'agreement_signed')) then 'booked'
      when l.status = 'booked' then 'open'
      else l.status end
  where l.id = p_lead;
end $$;

create or replace function public.bookings_after_change() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    insert into public.booking_status_history (booking_id, branch_id, associate_id, status_before, status_after, changed_by)
    values (new.id, new.branch_id, new.associate_id, null, new.status, auth.uid());
  elsif new.status is distinct from old.status then
    insert into public.booking_status_history (booking_id, branch_id, associate_id, status_before, status_after, changed_by)
    values (new.id, new.branch_id, new.associate_id, old.status, new.status, auth.uid());
  end if;
  perform public.refresh_lead_status(new.lead_id);
  return null;
end $$;
create trigger bookings_after_insert after insert on public.bookings
  for each row execute function public.bookings_after_change();
create trigger bookings_after_update after update of status, deleted_at on public.bookings
  for each row execute function public.bookings_after_change();

-- ================================================================ append-only history
create or replace function public.history_guard() returns trigger
language plpgsql as $$
begin
  if tg_op = 'DELETE' then
    raise exception '% is append-only: rows cannot be deleted (soft-delete instead)', tg_table_name using errcode = '42501';
  end if;
  -- only the soft-delete bookkeeping columns may change
  -- (generated search columns are not yet computed inside a BEFORE trigger, so they are ignored)
  if (to_jsonb(new) - array['deleted_at', 'updated_at', 'remark_tsv'])
     is distinct from (to_jsonb(old) - array['deleted_at', 'updated_at', 'remark_tsv']) then
    raise exception '% is append-only: add a new entry instead of editing history', tg_table_name using errcode = '42501';
  end if;
  return new;
end $$;
create trigger interactions_history_guard before update or delete on public.interactions
  for each row execute function public.history_guard();
create trigger cp_interactions_history_guard before update or delete on public.cp_interactions
  for each row execute function public.history_guard();
create trigger booking_history_guard before update or delete on public.booking_status_history
  for each row execute function public.history_guard();

create or replace function public.audit_log_guard() returns trigger
language plpgsql as $$
begin
  raise exception 'audit_log is immutable' using errcode = '42501';
end $$;
create trigger audit_log_immutable before update or delete on public.audit_log
  for each row execute function public.audit_log_guard();

-- ================================================================ audit trail
create or replace function public.audit_row() returns trigger
language plpgsql security definer set search_path = public as $$
declare j jsonb; branch uuid;
begin
  j := to_jsonb(case when tg_op = 'DELETE' then old else new end);
  branch := coalesce((j ->> 'branch_id')::uuid, case when tg_table_name = 'branches' then (j ->> 'id')::uuid end);
  insert into public.audit_log (actor_id, branch_id, table_name, row_id, action, old_data, new_data)
  values (auth.uid(), branch, tg_table_name, (j ->> 'id')::uuid, tg_op,
          case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end,
          case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end);
  return null;
end $$;

do $$
declare t text;
begin
  foreach t in array array[
    'branches','profiles','projects','cold_reasons','next_action_types','review_cycle',
    'channel_partners','leads','bookings','targets','review_sessions','review_actions']
  loop
    execute format('create trigger %I after insert or update or delete on public.%I for each row execute function public.audit_row()',
                   t || '_audit', t);
  end loop;
end $$;
-- interactions are history themselves: audit only the (soft) edits
create trigger interactions_audit    after update on public.interactions    for each row execute function public.audit_row();
create trigger cp_interactions_audit after update on public.cp_interactions for each row execute function public.audit_row();


-- ===================== 20260101000003_rls.sql =====================
-- Branch Review OS - migration 3: Row Level Security.
--
-- Visibility rule (one function, used by every policy):
--   associate     -> own rows
--   team_lead     -> self + everyone below them via reports_to (recursive)
--   branch_admin  -> everyone in their branch
--   super_admin   -> everyone in every branch
--
-- Soft-deleted rows are NOT hidden by policies (a policy that hides a row also blocks the
-- UPDATE that soft-deletes it). Queries and metric views filter `deleted_at is null`.

-- ================================================================ helper functions
create or replace function public.my_role() returns public.user_role
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid() and active and deleted_at is null
$$;

create or replace function public.my_branch() returns uuid
language sql stable security definer set search_path = public as $$
  select branch_id from public.profiles where id = auth.uid() and active and deleted_at is null
$$;

create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.my_role() in ('branch_admin', 'super_admin'), false)
$$;

create or replace function public.is_reviewer() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.my_role() in ('team_lead', 'branch_admin', 'super_admin'), false)
$$;

create or replace function public.visible_associates() returns setof uuid
language sql stable security definer set search_path = public as $$
  with recursive me as (
    select id, role, branch_id from public.profiles
     where id = auth.uid() and active and deleted_at is null
  ), tree(id) as (
    select id from me
    union                                   -- UNION (not ALL) so a reporting loop cannot recurse forever
    select c.id from public.profiles c join tree t on c.reports_to = t.id
  )
  select p.id from public.profiles p cross join me
   where me.role = 'super_admin'
      or (me.role = 'branch_admin' and p.branch_id = me.branch_id)
      or (me.role = 'team_lead'    and p.id in (select id from tree))
      or p.id = me.id
$$;

-- Used by the keep-alive job: proves the database is awake without needing a login.
create or replace function public.ping() returns timestamptz
language sql stable security definer set search_path = public as $$ select now() $$;

-- ================================================================ privileges
revoke all on all tables    in schema public from anon;
revoke all on all functions in schema public from anon, public;
grant usage on schema public to anon, authenticated, service_role;

grant select, insert, update on all tables in schema public to authenticated;
grant all on all tables in schema public to service_role;
alter default privileges in schema public grant select, insert, update on tables to authenticated;
grant usage, select on all sequences in schema public to authenticated, service_role;

grant execute on function public.my_role(), public.my_branch(), public.is_admin(), public.is_reviewer(),
                          public.visible_associates() to authenticated, service_role;
grant execute on function public.ping() to anon, authenticated, service_role;

-- ================================================================ enable RLS
do $$
declare t text;
begin
  foreach t in array array[
    'branches','profiles','projects','cold_reasons','next_action_types','review_cycle',
    'channel_partners','leads','interactions','cp_interactions','bookings',
    'booking_status_history','targets','review_sessions','review_actions','audit_log']
  loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
end $$;

-- ================================================================ branches / profiles
create policy branches_select on public.branches for select to authenticated
  using (id = public.my_branch() or public.my_role() = 'super_admin');
create policy branches_write on public.branches for all to authenticated
  using (public.my_role() = 'super_admin') with check (public.my_role() = 'super_admin');

create policy profiles_select on public.profiles for select to authenticated
  using (id in (select public.visible_associates()));
-- Users may edit only their own row (the guard trigger limits which columns).
-- Creating users and changing roles is done server-side with the service key.
create policy profiles_update_self on public.profiles for update to authenticated
  using (id = auth.uid() and public.my_role() is not null)
  with check (id = auth.uid());

-- ================================================================ config (read: everyone signed in; write: admins)
do $$
declare t text;
begin
  foreach t in array array['projects','cold_reasons','next_action_types','review_cycle']
  loop
    execute format('create policy %I on public.%I for select to authenticated using (public.my_role() is not null)',
                   t || '_select', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (public.is_admin())',
                   t || '_insert', t);
    execute format('create policy %I on public.%I for update to authenticated using (public.is_admin()) with check (public.is_admin())',
                   t || '_update', t);
  end loop;
end $$;

-- review cycles belong to one branch: admins may only change their own branch's cycle
drop policy review_cycle_insert on public.review_cycle;
drop policy review_cycle_update on public.review_cycle;
create policy review_cycle_insert on public.review_cycle for insert to authenticated
  with check (public.is_admin() and (branch_id = public.my_branch() or public.my_role() = 'super_admin'));
create policy review_cycle_update on public.review_cycle for update to authenticated
  using (public.is_admin() and (branch_id = public.my_branch() or public.my_role() = 'super_admin'))
  with check (public.is_admin() and (branch_id = public.my_branch() or public.my_role() = 'super_admin'));

-- ================================================================ channel partners
-- The CP directory is shared inside a branch (so two associates meeting the same CP
-- do not create duplicates). CP *meetings* (cp_interactions) stay private to the associate.
create policy cp_select on public.channel_partners for select to authenticated
  using (branch_id = public.my_branch() or public.my_role() = 'super_admin');
create policy cp_insert on public.channel_partners for insert to authenticated
  with check (branch_id = public.my_branch() or public.my_role() = 'super_admin');
create policy cp_update on public.channel_partners for update to authenticated
  using (created_by = auth.uid()
         or (public.is_admin() and (branch_id = public.my_branch() or public.my_role() = 'super_admin')))
  with check (branch_id = public.my_branch() or public.my_role() = 'super_admin');

-- ================================================================ leads
create policy leads_select on public.leads for select to authenticated
  using (owner_id in (select public.visible_associates()));
create policy leads_insert on public.leads for insert to authenticated
  with check (owner_id in (select public.visible_associates()));
create policy leads_update on public.leads for update to authenticated
  using (owner_id in (select public.visible_associates()))
  with check (owner_id in (select public.visible_associates()));

-- ================================================================ interactions
create policy interactions_select on public.interactions for select to authenticated
  using (associate_id in (select public.visible_associates()));
create policy interactions_insert on public.interactions for insert to authenticated
  with check (associate_id in (select public.visible_associates())
              and lead_id in (select id from public.leads));          -- leads RLS applies here
create policy interactions_update on public.interactions for update to authenticated
  using (associate_id in (select public.visible_associates()))
  with check (associate_id in (select public.visible_associates()));

create policy cp_interactions_select on public.cp_interactions for select to authenticated
  using (associate_id in (select public.visible_associates()));
create policy cp_interactions_insert on public.cp_interactions for insert to authenticated
  with check (associate_id in (select public.visible_associates())
              and cp_id in (select id from public.channel_partners));
create policy cp_interactions_update on public.cp_interactions for update to authenticated
  using (associate_id in (select public.visible_associates()))
  with check (associate_id in (select public.visible_associates()));

-- ================================================================ bookings
create policy bookings_select on public.bookings for select to authenticated
  using (associate_id in (select public.visible_associates()));
create policy bookings_insert on public.bookings for insert to authenticated
  with check (associate_id in (select public.visible_associates())
              and lead_id in (select id from public.leads));
create policy bookings_update on public.bookings for update to authenticated
  using (associate_id in (select public.visible_associates()))
  with check (associate_id in (select public.visible_associates()));

-- history rows are written only by triggers
create policy booking_history_select on public.booking_status_history for select to authenticated
  using (associate_id in (select public.visible_associates()));

-- ================================================================ targets (set by reviewers for people below them)
create policy targets_select on public.targets for select to authenticated
  using (associate_id in (select public.visible_associates()));
create policy targets_insert on public.targets for insert to authenticated
  with check (public.is_reviewer() and associate_id in (select public.visible_associates()));
create policy targets_update on public.targets for update to authenticated
  using (public.is_reviewer() and associate_id in (select public.visible_associates()))
  with check (public.is_reviewer() and associate_id in (select public.visible_associates()));

-- ================================================================ review sessions & actions
create policy review_sessions_select on public.review_sessions for select to authenticated
  using (public.is_reviewer() and (created_by = auth.uid()
         or (public.is_admin() and (branch_id = public.my_branch() or public.my_role() = 'super_admin'))));
create policy review_sessions_insert on public.review_sessions for insert to authenticated
  with check (public.is_reviewer() and (branch_id = public.my_branch() or public.my_role() = 'super_admin'));
create policy review_sessions_update on public.review_sessions for update to authenticated
  using (public.is_reviewer() and (created_by = auth.uid()
         or (public.is_admin() and (branch_id = public.my_branch() or public.my_role() = 'super_admin'))))
  with check (public.is_reviewer());

-- the person who must act can see (and tick off) their own actions
create policy review_actions_select on public.review_actions for select to authenticated
  using (associate_id in (select public.visible_associates()) or created_by = auth.uid());
create policy review_actions_insert on public.review_actions for insert to authenticated
  with check (public.is_reviewer() and associate_id in (select public.visible_associates()));
create policy review_actions_update on public.review_actions for update to authenticated
  using (associate_id in (select public.visible_associates()) or created_by = auth.uid())
  with check (associate_id in (select public.visible_associates()) or created_by = auth.uid());

-- ================================================================ audit log (read-only for admins)
create policy audit_log_select on public.audit_log for select to authenticated
  using (public.is_admin() and (branch_id = public.my_branch() or public.my_role() = 'super_admin'));


-- ===================== 20260101000004_metrics.sql =====================
-- Branch Review OS - migration 4: THE metric dictionary (see docs/metrics.md).
-- Every dashboard number comes from these functions. They run as the caller
-- (security invoker) so Row Level Security decides whose numbers each user can see.

-- ---------------------------------------------------------------- review period resolver
-- Resolves the review window containing p_on from the branch's review_cycle rows.
-- Default cycle: 1-10, 11-20, 21-end of month.
create or replace function public.current_review_period(p_on date default ((now() at time zone 'Asia/Kolkata')::date))
returns table (label text, period_start date, period_end date)
language sql stable security invoker set search_path = public as $$
  with m as (
    select date_trunc('month', p_on)::date as first_day,
           (date_trunc('month', p_on) + interval '1 month - 1 day')::date as last_day
  )
  select rc.label,
         (m.first_day + (rc.start_day - 1))::date,
         least(coalesce(m.first_day + (rc.end_day - 1), m.last_day), m.last_day)::date
    from public.review_cycle rc, m
   where rc.deleted_at is null
     and rc.branch_id = public.my_branch()
     and p_on between (m.first_day + (rc.start_day - 1)) and least(coalesce(m.first_day + (rc.end_day - 1), m.last_day), m.last_day)
   order by rc.sort_order
   limit 1
$$;

-- ---------------------------------------------------------------- per-associate metrics
-- Definitions (identical to docs/metrics.md):
--   customer_meetings = interactions of type 'meeting' with occurred_on in the period
--   leads_met         = distinct leads with >= 1 meeting in the period
--   hot/warm/cold     = leads_met split by the lead's rating after its LAST meeting in the period
--   hot_pct           = hot_leads / leads_met
--   cps_met           = distinct CPs with >= 1 CP interaction in the period
--   cp_*              = cps_met split by the CP's rating after its LAST CP interaction in the period
--   bookings          = bookings with status in (booking_done, agreement_signed), booking_date in the period
--   booking_value     = sum(value) of those same bookings
--   tokens(+value)    = status = token            (reported separately, never in bookings)
--   cancelled(+value) = status = cancelled        (excluded from bookings, always reported)
create or replace function public.associate_metrics(p_from date, p_to date)
returns table (
  associate_id uuid, associate_name text,
  customer_meetings int, leads_met int, hot_leads int, warm_leads int, cold_leads int, hot_pct numeric,
  cps_met int, cp_active int, cp_hot int, cp_warm int, cp_cold int,
  bookings int, booking_value numeric,
  tokens int, token_value numeric,
  cancelled int, cancelled_value numeric
)
language sql stable security invoker set search_path = public as $$
  with people as (
    select p.id, p.full_name from public.profiles p
     where p.deleted_at is null and p.active and p.role in ('associate', 'team_lead')
  ),
  mtg as (
    select i.associate_id, i.lead_id, i.rating_after, i.occurred_on, i.created_at
      from public.interactions i
     where i.deleted_at is null and i.interaction_type = 'meeting' and i.occurred_on between p_from and p_to
  ),
  mtg_last as (
    select distinct on (associate_id, lead_id) associate_id, lead_id, rating_after
      from mtg order by associate_id, lead_id, occurred_on desc, created_at desc
  ),
  m as (
    select associate_id,
           (select count(*) from mtg x where x.associate_id = l.associate_id)::int as meetings,
           count(*)::int as leads_met,
           count(*) filter (where rating_after = 'hot')::int  as hot_leads,
           count(*) filter (where rating_after = 'warm')::int as warm_leads,
           count(*) filter (where rating_after = 'cold')::int as cold_leads
      from mtg_last l group by associate_id
  ),
  cpi as (
    select c.associate_id, c.cp_id, c.rating_after, c.occurred_on, c.created_at
      from public.cp_interactions c
     where c.deleted_at is null and c.occurred_on between p_from and p_to
  ),
  cp_last as (
    select distinct on (associate_id, cp_id) associate_id, cp_id, rating_after
      from cpi order by associate_id, cp_id, occurred_on desc, created_at desc
  ),
  c as (
    select associate_id, count(*)::int as cps_met,
           count(*) filter (where rating_after = 'active')::int as cp_active,
           count(*) filter (where rating_after = 'hot')::int    as cp_hot,
           count(*) filter (where rating_after = 'warm')::int   as cp_warm,
           count(*) filter (where rating_after = 'cold')::int   as cp_cold
      from cp_last group by associate_id
  ),
  b as (
    select associate_id,
           count(*) filter (where status in ('booking_done', 'agreement_signed'))::int as bookings,
           coalesce(sum(value) filter (where status in ('booking_done', 'agreement_signed')), 0) as booking_value,
           count(*) filter (where status = 'token')::int as tokens,
           coalesce(sum(value) filter (where status = 'token'), 0) as token_value,
           count(*) filter (where status = 'cancelled')::int as cancelled,
           coalesce(sum(value) filter (where status = 'cancelled'), 0) as cancelled_value
      from public.bookings
     where deleted_at is null and booking_date between p_from and p_to
     group by associate_id
  )
  select p.id, p.full_name,
         coalesce(m.meetings, 0), coalesce(m.leads_met, 0),
         coalesce(m.hot_leads, 0), coalesce(m.warm_leads, 0), coalesce(m.cold_leads, 0),
         case when coalesce(m.leads_met, 0) = 0 then 0 else round(m.hot_leads::numeric / m.leads_met, 4) end,
         coalesce(c.cps_met, 0), coalesce(c.cp_active, 0), coalesce(c.cp_hot, 0), coalesce(c.cp_warm, 0), coalesce(c.cp_cold, 0),
         coalesce(b.bookings, 0), coalesce(b.booking_value, 0),
         coalesce(b.tokens, 0), coalesce(b.token_value, 0),
         coalesce(b.cancelled, 0), coalesce(b.cancelled_value, 0)
    from people p
    left join m on m.associate_id = p.id
    left join c on c.associate_id = p.id
    left join b on b.associate_id = p.id
   where p.id in (select public.visible_associates())
   order by p.full_name
$$;

-- ---------------------------------------------------------------- totals for the people the caller can see
create or replace function public.team_metrics(p_from date, p_to date)
returns table (
  customer_meetings int, leads_met int, hot_leads int, warm_leads int, cold_leads int, hot_pct numeric,
  cps_met int, cp_active int, cp_hot int, cp_warm int, cp_cold int,
  bookings int, booking_value numeric, tokens int, token_value numeric, cancelled int, cancelled_value numeric
)
language sql stable security invoker set search_path = public as $$
  select coalesce(sum(customer_meetings), 0)::int, coalesce(sum(leads_met), 0)::int,
         coalesce(sum(hot_leads), 0)::int, coalesce(sum(warm_leads), 0)::int, coalesce(sum(cold_leads), 0)::int,
         case when coalesce(sum(leads_met), 0) = 0 then 0 else round(sum(hot_leads)::numeric / sum(leads_met), 4) end,
         coalesce(sum(cps_met), 0)::int, coalesce(sum(cp_active), 0)::int, coalesce(sum(cp_hot), 0)::int,
         coalesce(sum(cp_warm), 0)::int, coalesce(sum(cp_cold), 0)::int,
         coalesce(sum(bookings), 0)::int, coalesce(sum(booking_value), 0),
         coalesce(sum(tokens), 0)::int, coalesce(sum(token_value), 0),
         coalesce(sum(cancelled), 0)::int, coalesce(sum(cancelled_value), 0)
    from public.associate_metrics(p_from, p_to)
$$;

grant execute on function public.current_review_period(date), public.associate_metrics(date, date),
                          public.team_metrics(date, date) to authenticated, service_role;

revoke execute on function public.current_review_period(date), public.associate_metrics(date, date),
                           public.team_metrics(date, date) from public, anon;


-- ===================== 20260101000005_legacy_key_and_login_limits.sql =====================
-- Branch Review OS - migration 5: link to the legacy Excel users + login rate limiting.

-- ---------------------------------------------------------------- legacy_key
-- The `user_key` from the import workbook ('parul', 'udit', ...). Lets the data import
-- attach each Excel tab to the right profile without guessing from names.
alter table public.profiles add column legacy_key text;
create unique index profiles_legacy_key_uq on public.profiles (legacy_key) where legacy_key is not null;

-- legacy_key, like role and branch, can only be changed server-side with the service key.
create or replace function public.profiles_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null then
    if new.role        is distinct from old.role
    or new.branch_id   is distinct from old.branch_id
    or new.reports_to  is distinct from old.reports_to
    or new.active      is distinct from old.active
    or new.designation is distinct from old.designation
    or new.email       is distinct from old.email
    or new.legacy_key  is distinct from old.legacy_key
    or new.deleted_at  is distinct from old.deleted_at then
      raise exception 'You cannot change role, branch, reporting line, status or designation from the app. Ask an admin.'
        using errcode = '42501';
    end if;
    if new.must_change_password and not old.must_change_password then
      raise exception 'must_change_password can only be switched on by an admin' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------- login attempts
-- Written and read ONLY by the server (service key). RLS is on with no policies,
-- and all browser roles are revoked, so nobody can read who tried to log in.
create table public.login_attempts (
  id         bigint generated always as identity primary key,
  email      text not null,
  ip         text not null,
  succeeded  boolean not null,
  at         timestamptz not null default now()
);
create index login_attempts_email_idx on public.login_attempts (email, at desc);
create index login_attempts_ip_idx    on public.login_attempts (ip, at desc);
alter table public.login_attempts enable row level security;
revoke all on public.login_attempts from anon, authenticated, public;
grant all on public.login_attempts to service_role;


-- ===================== 20260101000006_history.sql =====================
-- Flat workbook support. Old migrations remain unchanged.
alter table public.profiles add column if not exists legacy_key text unique;
alter table public.profiles add column is_historical boolean not null default false;
alter table public.projects add column legacy_key text unique, add column aliases_seen text, add column is_historical boolean not null default false;
create table public.cp_firms (
 id uuid primary key default gen_random_uuid(), legacy_key text unique, branch_id uuid not null references public.branches,
 name text not null, aliases_seen text, is_freelancer_bucket boolean not null default false,
 cp_people_count integer, booking_rows_count integer, raw_json jsonb,
 is_historical boolean not null default false, created_by uuid references public.profiles,
